const e = $json.execution ?? {};
const knownNodes = ['Intake form','Validate intake','Classify','Validate classification','Document question','Enqueue','Poll budget','Wait for job','Poll job','Validate job','Job done','Job failed','Stop failed job','Prepare draft','Review draft','Approved','Send reply','No reply'];
const node = knownNodes.includes(e.lastNodeExecuted) ? e.lastNodeExecuted : 'unknown';
const id = typeof e.id === 'string' && /^[0-9]{1,20}$/.test(e.id) ? e.id : 'unavailable';
const status = String(e.error?.httpCode ?? e.error?.statusCode ?? '');
let reason = 'execution_error';
if ($json.trigger) reason = 'trigger_error';
else if (node === 'Stop failed job') reason = 'job_failed';
else if (node === 'Poll budget') reason = 'poll_timeout';
else if (status === '429') reason = 'http_429';
else if (status === '503') reason = 'http_503';
const link = id === 'unavailable' ? 'Open local n8n Executions.' : 'http://127.0.0.1:5678/workflow/bankIntakeToReply/executions/' + id;
return [{json: {text: ['Bank Assistant intake failed; operator action required.', 'Reason: ' + reason, 'Node: ' + node, 'Execution: ' + id, link, 'Inspect locally with authorized access. Check API/worker/Redis and SMTP before retrying; do not replay POST /ask/jobs blindly.'].join('\n')}}];
